/**
 * Runtime helpers over a ResolvedComposition. Preset selection and
 * validation happen HERE, at use time — not at compile time — because the
 * preset can change per session (config slice) and per settings hot reload.
 */
import type { AgentPreset } from "../preset/index.js";
import type { BuiltinTool } from "../tool-system/builtin/index.js";
import type { ExtensionTool } from "../tool-system/capability-module.js";
import type { ResolvedComposition } from "./types.js";
import { ConfigError } from "../exceptions.js";
import { LifetimeScope, type DisposableLike, type Dispose } from "./lifetime.js";

/** Resolve a preset by name (or the composition default), failing loud. */
export function resolvePresetFromComposition(
  composition: ResolvedComposition,
  name?: string,
): AgentPreset {
  const resolvedName = name || composition.engine.defaultPreset;
  const found = composition.engine.presets.find((p) => p.key === resolvedName);
  if (found) return found.value;
  const allowed = composition.engine.presets.map((p) => p.key).join(", ");
  throw new Error(`Unknown agent preset "${resolvedName}". Available presets: ${allowed}`);
}

/** All preset-tags tools — the composed catalog in effective order. */
export function compositionToolCatalog(composition: ResolvedComposition): BuiltinTool[] {
  return composition.engine.tools.flatMap((t) => (t.kind === "preset-tags" ? [t.tool] : []));
}

/**
 * Preset-tags tools force-joined to the ACTIVE preset regardless of its name.
 * Rule: tools owned by modules that contribute no presets (pet-style catalog
 * tools) — presets snapshot their tool lists from catalogs known at module
 * authoring time, which can never include such packages. Modules that DO
 * contribute presets (core, coding) reference their tools via preset tags
 * already. Visibility stays gated by each tool's exposure.availability.
 */
export function presetInjectedTools(composition: ResolvedComposition): BuiltinTool[] {
  const presetOwners = new Set(composition.engine.presets.map((p) => p.moduleId));
  return composition.engine.tools.flatMap((t) =>
    t.kind === "preset-tags" && !presetOwners.has(t.moduleId) ? [t.tool] : [],
  );
}

/** Module-contributed named prompt sections as a plain record. */
export function compositionPromptSections(
  composition: ResolvedComposition,
): Record<string, string> {
  return Object.fromEntries(composition.engine.promptSections.map((s) => [s.key, s.value]));
}

/**
 * Register always-exposure tools on the engine-local registry fork.
 * Cross-module uniqueness is compiler-enforced; this guards collisions with
 * runtime-registered tools.
 */
export function registerAlwaysTools(
  composition: ResolvedComposition,
  registry: {
    hasTool(name: string): boolean;
    registerTool(
      definition: ExtensionTool["definition"],
      execute: ExtensionTool["execute"],
    ): DisposableLike;
  },
): Dispose {
  const owner = new LifetimeScope("engine", "always-tools");
  try {
    for (const contribution of composition.engine.tools) {
      if (contribution.kind !== "always") continue;
      const name = contribution.tool.definition.name;
      if (registry.hasTool(name)) {
        throw new ConfigError(`Capability tool conflicts with registered tool: ${name}`, {
          duplicateCapabilityTool: name,
          capabilityId: contribution.moduleId,
        });
      }
      owner.own(registry.registerTool(contribution.tool.definition, contribution.tool.execute));
    }
  } catch (error) {
    void owner.dispose().catch(() => {});
    throw error;
  }
  return () => owner.dispose();
}

/** First non-null module instruction boundary, in module order. */
export function resolveCompositionInstructionBoundary(
  composition: ResolvedComposition,
  cwd: string,
): string | null {
  for (const boundary of composition.engine.instructionBoundaries) {
    const found = boundary.value(cwd);
    if (found) return found;
  }
  return null;
}

export interface AgentEngineContributions {
  readonly tools?: readonly AgentModuleToolContribution[];
  readonly presets?: readonly AgentPreset[];
  /** Preset used when the host does not choose one. At most one module may declare it. */
  readonly defaultPreset?: string;
  readonly promptSections?: Readonly<Record<string, string>>;
  readonly dynamicContextProviders?: readonly CapabilityDynamicContextProvider[];

}

export interface ResolvedContribution<T> {
  readonly key: string;
  readonly moduleId: string;
  readonly value: T;
}

export type ResolvedToolContribution =
  | { readonly kind: "preset-tags"; readonly moduleId: string; readonly tool: BuiltinTool }
  | { readonly kind: "always"; readonly moduleId: string; readonly tool: ExtensionTool };

export interface ResolvedEngineHook {
  readonly moduleId: string;
  readonly event: HookEventName;
  readonly handler: CapabilityEngineHookContribution["handler"];
  readonly priority: number;
  readonly name: string;
}

export interface ResolvedEngineComposition {
  /**
   * Effective registry order: every preset-tags tool (module order) first,
   * then every always tool (module order) — mirrors the current engine's
   * composeToolCatalog() + registerExtensionModules() sequence.
   */
  readonly tools: readonly ResolvedToolContribution[];
  readonly presets: readonly ResolvedContribution<AgentPreset>[];
  readonly defaultPreset: string;
  readonly promptSections: readonly ResolvedContribution<string>[];
  readonly dynamicContextProviders: readonly ResolvedContribution<CapabilityDynamicContextProvider>[];

// mirrors resolveAgentPreset(), which resolves capability-contributed
// presets before builtins (e.g. coding's extended "general"). The shadow is
// surfaced as a diagnostic; host-vs-host duplicates still fail loud.
const presets: Array<ResolvedContribution<AgentPreset>> = [];
const presetIndex = new Map<string, number>();
const coreModuleId = registered[0]?.resolved.id ?? "core";
for (const { module } of registered) {
  for (const preset of module.engine?.presets ?? []) {
    const existing = presetIndex.get(preset.name);
    if (existing === undefined) {
      presetIndex.set(preset.name, presets.length);
      presets.push({ key: preset.name, moduleId: module.id, value: preset });
      continue;
    }
    const owner = presets[existing];
    if (!owner || owner.moduleId !== coreModuleId) {
      throw duplicate("preset", preset.name, owner?.moduleId ?? coreModuleId, module.id);
    }
    presets[existing] = { key: preset.name, moduleId: module.id, value: preset };
    diagnostics.push({
      code: "core_preset_shadowed",
      moduleId: module.id,
      message: `Module "${module.id}" shadows core preset "${preset.name}"`,
    });
  }
}

// Default preset: at most one distinct declaration wins; none → core default.
let defaultPreset: { name: string; moduleId: string } | undefined;
for (const { module } of registered) {
  const declared = module.engine?.defaultPreset;
  if (!declared) continue;
  if (defaultPreset && defaultPreset.name !== declared) {
    throw new CompositionError(
      `Conflicting default presets: "${defaultPreset.name}" (${defaultPreset.moduleId}) vs "${declared}" (${module.id})`,
      {
        code: "conflicting_default_preset",
        key: declared,
        firstModuleId: defaultPreset.moduleId,
        secondModuleId: module.id,
      },
    );
  }
  defaultPreset ??= { name: declared, moduleId: module.id };
}
const defaultPresetName = defaultPreset?.name ?? DEFAULT_AGENT_PRESET;
if (!presets.some((p) => p.key === defaultPresetName)) {
  throw new CompositionError(`Default preset "${defaultPresetName}" is not contributed`, {
    code: "unknown_default_preset",
    key: defaultPresetName,
    firstModuleId: defaultPreset?.moduleId ?? "core",
  });
}

// Preset tool references must resolve to preset-tags tools.
const presetTagToolNames = new Set(presetTagTools.map((t) => t.tool.definition.name));
for (const { key, moduleId, value } of presets) {
  for (const toolName of value.builtinTools) {
    if (!presetTagToolNames.has(toolName)) {
      throw new CompositionError(`Preset "${key}" references unknown tool "${toolName}"`, {
        code: "unknown_preset_tool",
        key: toolName,
        firstModuleId: moduleId,
      });
    }
  }
}

const promptSections = collectKeyed(registered, "prompt section", (m) =>
  Object.entries(m.engine?.promptSections ?? {}),
);

// Single composition fact source for every module contribution.
this.composition =
  config.composition ?? compileComposition({ modules: config.modules ?? [] });
this.toolCatalog = compositionToolCatalog(this.composition);
this.toolGuards = new Map(
  this.toolCatalog.flatMap((tool) =>
    tool.exposure.availability
      ? ([[tool.definition.name, tool.exposure.availability]] as const)
      : [],
  ),
);
this.toolRewriters = new Map(
  this.toolCatalog.flatMap((tool) =>
    tool.exposure.rewriteDefinition
      ? ([[tool.definition.name, tool.exposure.rewriteDefinition]] as const)
      : [],
  ),
);
// Behavior profile registry: core defaults first, then host config, then
// module contributions — later registrations override earlier ones by id.
const moduleProfiles = this.composition.engine.behaviorProfiles;
this.behaviorProfiles = new Map(
  [
    ...moduleProfiles.filter((p) => p.moduleId === "core").map((p) => p.value),
    ...(config.behaviorProfiles ?? []),
    ...moduleProfiles.filter((p) => p.moduleId !== "core").map((p) => p.value),
  ].map((profile) => [profile.id, profile] as const),
);
this.capabilityPromptSections = compositionPromptSections(this.composition);
this.capabilityDynamicContextProviders = this.composition.engine.dynamicContextProviders.map(
  (c) => c.value,
);
this.preset = resolvePresetFromComposition(this.composition, config.preset);
// Catalog tools owned by modules that contribute no presets join the
// active preset regardless of its name: presets snapshot their tool lists
// from catalogs known at module authoring time, which can never include
// such packages. Visibility stays gated by exposure.availability.
const injectedTools = presetInjectedTools(this.composition);
if (injectedTools.length > 0) {
  this.preset = {
    ...this.preset,
    builtinTools: [
      ...this.preset.builtinTools,
      ...injectedTools.map((tool) => tool.definition.name),
    ],
